import{_ as t,o as a,c as r,a3 as n}from"./chunks/framework.DQ-7HQaQ.js";const p=JSON.parse('{"title":"Embeddings, similarity and the evidence they miss","description":"Learn why numerical representations help retrieve text, inspect cosine similarity, and verify model output without treating similarity as truth.","frontmatter":{"title":"Embeddings, similarity and the evidence they miss","description":"Learn why numerical representations help retrieve text, inspect cosine similarity, and verify model output without treating similarity as truth."},"headers":[],"relativePath":"students/embeddings.md","filePath":"students/embeddings.md","lastUpdated":1794433168000}'),o={name:"students/embeddings.md"};function i(s,e,d,l,c,h){return a(),r("div",null,[...e[0]||(e[0]=[n('<h1 id="embeddings-how-can-a-computer-find-related-ideas" tabindex="-1">Embeddings: how can a computer find related ideas? <a class="header-anchor" href="#embeddings-how-can-a-computer-find-related-ideas" aria-label="Permalink to &quot;Embeddings: how can a computer find related ideas?&quot;">​</a></h1><p>Imagine someone asks a club&#39;s assistant, <strong>“Where can I get help joining?”</strong> The membership guide might say <strong>“Contact the club secretary for application assistance.”</strong> The words are different, but the meaning is related. Keyword search can miss paraphrases. Embeddings give us another way to search.</p><p><strong>An embedding is a numerical representation produced by a model.</strong> For many text-retrieval models, it is a fixed-length vector of real numbers. The model is trained so related texts tend to be closer under a selected similarity measure. An embedding does <strong>not</strong> store an authoritative fact or prove two claims are true.</p><h2 id="the-people-and-the-question" tabindex="-1">The people and the question <a class="header-anchor" href="#the-people-and-the-question" aria-label="Permalink to &quot;The people and the question&quot;">​</a></h2><p>Researchers had the <em>document matching</em> problem long before modern LLMs. Gerard Salton and colleagues&#39; information-retrieval work explored representing documents in mathematical spaces. <a href="https://ecommons.cornell.edu/entities/publication/dc340f22-1c38-4f0a-921e-27706685b1bf" target="_blank" rel="noreferrer">Read the 1974 Cornell paper</a>. The vector-space concept evolved over time; don&#39;t confuse early term-weighted document vectors with today&#39;s neural embeddings.</p><p>In 2013, <strong>Tomas Mikolov and colleagues</strong> published <a href="https://arxiv.org/abs/1301.3781" target="_blank" rel="noreferrer">efficient neural word representations</a>. In 2019, <strong>Nils Reimers and Iryna Gurevych</strong> introduced <a href="https://aclanthology.org/D19-1410/" target="_blank" rel="noreferrer">Sentence-BERT</a> for useful sentence representations in similarity search. Their shared problem: <em>How can we compare language without checking every possible text pair with an expensive model?</em></p><h2 id="word-sentence-paragraph-and-chunk" tabindex="-1">Word, sentence, paragraph and chunk <a class="header-anchor" href="#word-sentence-paragraph-and-chunk" aria-label="Permalink to &quot;Word, sentence, paragraph and chunk&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Level</th><th>Example input</th><th>What the representation can help compare</th></tr></thead><tbody><tr><td>Word</td><td>“membership”</td><td>Terms (especially with older word-embedding methods)</td></tr><tr><td>Sentence</td><td>“Ask the secretary for help.”</td><td>One statement or intent</td></tr><tr><td>Paragraph</td><td>Several sentences describing applications</td><td>A coherent passage and its context</td></tr><tr><td>Chunk</td><td>A section of a long policy with a source ID</td><td>A retrievable passage with traceable provenance</td></tr></tbody></table><p>One modern embedding model may encode all of these input lengths, subject to its documented limits. <strong>A chunk is an input unit; an embedding is the vector computed from it.</strong> Their meanings are different.</p><h2 id="a-geometric-thought-experiment-not-a-model-output" tabindex="-1">A geometric thought experiment (not a model output) <a class="header-anchor" href="#a-geometric-thought-experiment-not-a-model-output" aria-label="Permalink to &quot;A geometric thought experiment (not a model output)&quot;">​</a></h2><p>Picture two feature directions: one for <em>membership</em> and one for <em>events</em>. We invent tiny vectors:</p><ul><li>Question about joining: <strong>q = (1, 0)</strong></li><li>Membership passage: <strong>a = (0.8, 0.6)</strong></li><li>Events passage: <strong>b = (0, 1)</strong></li></ul><p>Using <strong>cosine similarity</strong>, compare the directions rather than just the sizes:</p><p>[ \\operatorname{cos}(q,a)=\\frac{q\\cdot a}{\\lVert q\\rVert\\lVert a\\rVert}=0.8, \\qquad \\operatorname{cos}(q,b)=0. ]</p><p>So passage <strong>a</strong> ranks higher for this <em>invented</em> comparison. Real embeddings usually have many dimensions learned by a model; their individual coordinates generally do <strong>not</strong> correspond to human-named topics. <strong>These toy numbers were chosen for teaching and were never returned by an embedding API.</strong></p><p>An embedding workflow is:</p><p>```text Original document (S-membership) ↓ split into traceable chunks S-membership-C01 + its real text + source location ↓ configured embedding model Vector + model/version + chunk ID → stored index</p><p>Question → compatible query embedding → compare / rank vectors → retrieve the original text and source ID → give evidence to a model ```</p><p>Never compare vectors from incompatible embedding models as if they shared a coordinate system. Some retrieval models have different query/document input modes; follow the specific model&#39;s instructions.</p><h2 id="when-embeddings-help—and-fail" tabindex="-1">When embeddings help—and fail <a class="header-anchor" href="#when-embeddings-help—and-fail" aria-label="Permalink to &quot;When embeddings help—and fail&quot;">​</a></h2><p>Semantic retrieval may find paraphrases where exact-term search struggles. But it can also retrieve <strong>the wrong person with a similar biography</strong>, a near-opposite policy statement, or an old version of a rule. Cosine similarity is <strong>not a confidence probability</strong>, and a high score is not a source citation.</p><p>For your IS373 project, compare the same question with a <strong>keyword baseline</strong> and your <strong>chosen vector/graph retrieval</strong>. Inspect returned passage IDs, not only a generated answer. Record whether the cited original supports the specific claim.</p><h3 id="short-student-exercise" tabindex="-1">Short student exercise <a class="header-anchor" href="#short-student-exercise" aria-label="Permalink to &quot;Short student exercise&quot;">​</a></h3><ol><li>Predict which fictional club source answers <strong>“Who helps new applicants?”</strong> and write its expected source ID before searching.</li><li>Run the <a href="./reference#your-first-15-minutes">offline lexical lab</a>. Inspect the returned passage; explain any missed paraphrase.</li><li>If your local environment already supports an embedding model, follow the <a href="./reference#optional-add-a-real-model">optional real vector commands</a>, with the model ID recorded. Otherwise, <strong>label the vector comparison planned</strong>; no subscription is required for the offline step.</li><li>Compare one wrong or irrelevant result and explain how you would improve retrieval: source scope, metadata, chunking, an exact-term baseline, or a different model. Do not invent similarity scores.</li></ol><h3 id="ask-an-ai-coding-partner" tabindex="-1">Ask an AI coding partner <a class="header-anchor" href="#ask-an-ai-coding-partner" aria-label="Permalink to &quot;Ask an AI coding partner&quot;">​</a></h3><p>```text Teach me embeddings using one of my permitted documents and a real question. First distinguish word, sentence, paragraph and chunk representations. Show the original source ID, chunk boundaries and the retrieval result. If you use numeric vectors, say exactly which configured model generated them; label any invented vectors as illustrative. Explain cosine similarity, why the query/document embeddings must be compatible, and one failure case. Do not install packages or generate embeddings until I approve the plan. Ask me to check whether the retrieved passage really answers the question. ```</p><h3 id="a-note-from-the-ai" tabindex="-1">A note from the AI <a class="header-anchor" href="#a-note-from-the-ai" aria-label="Permalink to &quot;A note from the AI&quot;">​</a></h3><blockquote><p>I can rank passages by apparent relatedness. But I cannot turn a similarity score into evidence that a claim is true. When I return a passage, ask to see <strong>the original words, version and source location</strong>. Your judgment—and your tests—still matter.</p></blockquote><h2 id="go-deeper-when-ready" tabindex="-1">Go deeper, when ready <a class="header-anchor" href="#go-deeper-when-ready" aria-label="Permalink to &quot;Go deeper, when ready&quot;">​</a></h2><ul><li><a href="https://developers.openai.com/api/docs/guides/embeddings" target="_blank" rel="noreferrer">OpenAI embeddings guide</a> — model vectors, applications, similarity and limitations.</li><li><a href="https://sbert.net/examples/sentence_transformer/applications/semantic-search/" target="_blank" rel="noreferrer">Sentence Transformers semantic search</a> — query and corpus embeddings, similarity and retrieval.</li><li><a href="https://aclanthology.org/D19-1410/" target="_blank" rel="noreferrer">Sentence-BERT paper</a> — a historical research milestone.</li><li><a href="./chunking">Chunking handout</a> — how you choose the text units to embed.</li><li><a href="./check">How to evaluate</a> — accuracy and references, not just a plausible response.</li></ul><p><em>Educational examples, not measurements of any specific embedding model. References checked November 11, 2026.</em></p>',31)])])}const u=t(o,[["render",i]]);export{p as __pageData,u as default};
